from pathlib import Path
import json
import xml.etree.ElementTree as ET

root = Path("core/data/build/reports")
candidates = [p for p in root.rglob("*") if p.is_file() and "detekt" in str(p).lower()]
print("DETEKT_REPORT_FILES", [(str(p), p.stat().st_size) for p in candidates[:25]])
for p in candidates:
    try:
        if p.suffix == ".xml":
            tree = ET.parse(p)
            for file in tree.iter("file"):
                for issue in file.findall("error"):
                    print("DETEKT_ISSUE", file.attrib.get("name"), issue.attrib.get("line"),
                          issue.attrib.get("source"), issue.attrib.get("message"))
        elif p.suffix == ".sarif":
            data = json.loads(p.read_text())
            for run in data.get("runs", []):
                for finding in run.get("results", []):
                    for place in finding.get("locations", [])[:1]:
                        loc = place.get("physicalLocation", {})
                        print("DETEKT_SARIF", finding.get("ruleId"),
                              loc.get("artifactLocation", {}).get("uri"),
                              loc.get("region", {}).get("startLine"),
                              finding.get("message", {}).get("text"))
    except (ValueError, ET.ParseError, OSError) as error:
        print("REPORT_READ_FAILED", p, type(error).__name__)
PY
